for x,y,z,d in itertools.product(range(3),repeat=4):
 if all(Q[a,b,c]==(x*a+y*b+z*c+d)%3 for a,b,c in itertools.product(range(3),repeat=3)): print('LINEAR',x,y,z,d)
# second-coordinate affine dependence on qleft,qright for fixed p coords
coeff=np.zeros((3,3,3,3),int); bad=[]
for a,b,c in itertools.product(range(3),repeat=3):
 vals=q[R[np.ix_(groups[a],[groups[b][0]],groups[c])]].reshape(3,3)
 matches=[]
 for x,z,d in itertools.product(range(3),repeat=3):
  if all(vals[l,r]==(x*l+z*r+d)%3 for l,r in itertools.product(range(3),repeat=2)):matches.append((x,z,d))
 if matches:coeff[a,b,c]=matches[0]
 else:bad.append((a,b,c,vals.tolist()))
print('affine q fails',len(bad));print(bad[:5]); print('coeff',coeff)
